// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.maskingimport com.roshan.persona.persona.core.BuiltInPersonasimport com.roshan.persona.persona.core.PersonaProfileimport com.roshan.persona.persona.core.ProactiveStyleimport java.util.concurrent.atomic.AtomicBooleanimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Dynamic Filler Engine (Module 15 v3.0 — Step 15.4). * * Implements **Strategy A: Latency Masking** from strategy §5. * * When NOUS detects a complex classification, deep web search, or heavy * hardware operation, it does NOT leave the user in silence. Instead, it * **bypasses the LLM** and directly triggers Module 5 TTS with a * persona-appropriate filler sound. * * ## How it works * * ``` * User: "Hey NOUS, what's the capital of every country in Africa?" *   ↓ * Brain detects: estimated_processing_time > 1000ms (heavy query) *   ↓ * DynamicFillerEngine.shouldPlayFiller() → true *   ↓ * Bypass LLM → directly call TTS with persona filler *   ↓ * Atlas: "Give me a second, sir..." * Nova: "Hold on, let me think!" * Onyx: "Processing." *   ↓ * User feels heard instantly while Brain crunches data in background * ``` * * ## Filler categories * *  - **THINKING** — generic "let me think" (for LLM processing). *  - **SEARCHING** — "looking that up" (for web search). *  - **PROCESSING** — "working on it" (for hardware ops / agent tasks). *  - **CONTEXT_COMPRESSION** — "my mind is spinning" (for Token Survival / "nap"). * * Each category has per-persona variants (9 personas × 4 categories = 36 fillers). * * ## Cooldown * * Fillers are gated by a [fillerCooldownMs] cooldown (default 3 seconds). * Without this, a slow 10-second LLM call would spam 10 fillers. With the * cooldown, NOUS plays one filler at the start, then stays quiet until the * response arrives. * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§5 Token Survival & Latency Masking — Strategy A</a> */class DynamicFillerEngine(    private val config: FillerConfig = FillerConfig(),) {    /** True if a filler is currently playing (prevents overlap). */    private val fillerPlaying = AtomicBoolean(false)    /** Last filler play timestamp (for cooldown). */    private val lastFillerMs = AtomicLong(0)    /**     * Check if a filler should be played for the current operation.     *     * Returns true if:     *  - No filler is currently playing.     *  - The cooldown period has elapsed since the last filler.     *  - The estimated processing time exceeds the threshold.     *     * @param estimatedProcessingMs the Brain's estimate of how long the     *                               current operation will take.     * @param nowMs current epoch time (injectable for testing).     * @return true if a filler should be played.     */    fun shouldPlayFiller(        estimatedProcessingMs: Long,        nowMs: Long = System.currentTimeMillis(),    ): Boolean {        if (fillerPlaying.get()) return false  // already playing        if (estimatedProcessingMs < config.latencyThresholdMs) return false  // fast enough        val elapsed = nowMs - lastFillerMs.get()        if (elapsed < config.fillerCooldownMs) return false  // cooldown        return true    }    /**     * Get the appropriate filler text for [persona] + [category].     *     * Returns a persona-specific phrase that Module 5 TTS speaks immediately.     *     * @param persona the active persona.     * @param category the type of operation (THINKING, SEARCHING, PROCESSING, CONTEXT_COMPRESSION).     * @return the filler text, or null if the persona is SILENT (Wraith).     */    fun getFiller(persona: PersonaProfile, category: FillerCategory): String? {        // Silent personas (Wraith) don't use fillers — they stay quiet.        if (persona.proactiveStyle == ProactiveStyle.SILENT) return null        val fillers = FILLER_LIBRARY[category] ?: return null        val personaFillers = fillers[persona.id] ?: fillers["default"] ?: return null        // Cycle through fillers deterministically (avoids repeating the same one).        val index = ((lastFillerMs.get() / 1000) % personaFillers.size).toInt()        return personaFillers[index]    }    /**     * Mark that a filler has started playing.     *     * Called by the TTS engine when the filler audio begins. Prevents     * overlapping fillers.     *     * @param nowMs current epoch time (injectable for testing).     */    fun markFillerStarted(nowMs: Long = System.currentTimeMillis()) {        fillerPlaying.set(true)        lastFillerMs.set(nowMs)    }    /**     * Mark that the filler has finished playing.     *     * Called by the TTS engine when the filler audio completes. Allows     * the next filler to play (after cooldown).     */    fun markFillerFinished() {        fillerPlaying.set(false)    }    /** True if a filler is currently playing. */    fun isFillerPlaying(): Boolean = fillerPlaying.get()    /** Reset all state (for tests + Settings → Reset). */    fun reset() {        fillerPlaying.set(false)        lastFillerMs.set(0)    }    private companion object {        private const val TAG = "DynamicFillerEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** Categories of filler sounds (per strategy §5 + §12 Filler Sounds). */enum class FillerCategory(val displayLabel: String) {    /** Generic "let me think" — for LLM processing. */    THINKING("Thinking"),    /** "Looking that up" — for web search. */    SEARCHING("Searching"),    /** "Working on it" — for hardware ops / agent tasks. */    PROCESSING("Processing"),    /** "My mind is spinning" — for Token Survival / context compression ("nap"). */    CONTEXT_COMPRESSION("Context Compression"),}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for the filler engine. * * @param latencyThresholdMs minimum estimated processing time to trigger a *                            filler (default 1000ms per strategy §5). * @param fillerCooldownMs   minimum gap between fillers (default 3000ms — *                            prevents spam during long operations). */data class FillerConfig(    val latencyThresholdMs: Long = DEFAULT_LATENCY_THRESHOLD_MS,    val fillerCooldownMs: Long = DEFAULT_FILLER_COOLDOWN_MS,) {    init {        require(latencyThresholdMs > 0) { "latencyThresholdMs must be positive" }        require(fillerCooldownMs >= 0) { "fillerCooldownMs must be non-negative" }    }    companion object {        /** 1 second — operations faster than this don't need fillers. */        const val DEFAULT_LATENCY_THRESHOLD_MS = 1000L        /** 3 seconds — prevents filler spam during long operations. */        const val DEFAULT_FILLER_COOLDOWN_MS = 3000L    }}// ──────────────────────────────────────────────────────────────────────────/** * The filler library — per-persona, per-category filler phrases. * * 9 personas × 4 categories = 36 fillers (Wraith returns null for all * categories since it's SILENT). * * Each persona has 2-3 variants per category — the engine cycles through * them deterministically to avoid repetition. * * ## Design notes * *  - Fillers are SHORT (< 2 seconds TTS) — they're meant to fill silence, *    not deliver content. *  - Each persona's fillers match their voice: Atlas says "sir", Nova is *    casual, Onyx is terse, Sage is gentle, Aria is enthusiastic. *  - The "default" key is a fallback for custom personas that don't have *    specific fillers. */private val FILLER_LIBRARY: Map<FillerCategory, Map<String, List<String>>> = mapOf(    FillerCategory.THINKING to mapOf(        "atlas" to listOf("Give me a second, sir.", "One moment, if you please.", "Allow me to think."),        "nova" to listOf("Hold on, let me think!", "Give me a sec.", "One moment!"),        "onyx" to listOf("Processing.", "Calculating.", "Analyzing."),        "sage" to listOf("Let me think about that.", "Give me a moment.", "One second, let's consider this."),        "echo" to listOf("Hold up, thinking...", "Give me a sec.", "One moment."),        "vanguard" to listOf("Processing.", "Stand by.", "Computing."),        "aria" to listOf("Ooh, let me think!", "One second!", "Hold on, I've got this!"),        "zenith" to listOf("Give me a moment.", "Processing.", "One second."),        "default" to listOf("Let me think.", "One moment.", "Give me a second."),    ),    FillerCategory.SEARCHING to mapOf(        "atlas" to listOf("Let me look that up, sir.", "Searching now.", "Allow me to check."),        "nova" to listOf("Looking that up!", "Let me check.", "Searching now!"),        "onyx" to listOf("Searching.", "Querying.", "Retrieving."),        "sage" to listOf("Let me find that for you.", "Searching now.", "Let me look it up."),        "echo" to listOf("Looking it up...", "Let me check.", "Searching!"),        "vanguard" to listOf("Searching.", "Retrieving data.", "Querying sources."),        "aria" to listOf("Let me find it!", "Searching now!", "On it!"),        "zenith" to listOf("Searching.", "Retrieving.", "Looking it up."),        "default" to listOf("Let me check.", "Searching now.", "Looking that up."),    ),    FillerCategory.PROCESSING to mapOf(        "atlas" to listOf("Working on it, sir.", "Processing now.", "Almost there."),        "nova" to listOf("Working on it!", "Almost there!", "On it!"),        "onyx" to listOf("Executing.", "Processing.", "Working."),        "sage" to listOf("Working on it for you.", "Almost there.", "Just a moment."),        "echo" to listOf("Working on it...", "Almost done.", "On it!"),        "vanguard" to listOf("Executing.", "Processing.", "Mission in progress."),        "aria" to listOf("Working on it!", "Almost there!", "You got it!"),        "zenith" to listOf("Processing.", "Working on it.", "Almost there."),        "default" to listOf("Working on it.", "Processing.", "Almost there."),    ),    FillerCategory.CONTEXT_COMPRESSION to mapOf(        "atlas" to listOf("A moment, sir — organizing my thoughts.", "Bear with me briefly.", "One second, reorganizing."),        "nova" to listOf("Hold on, my mind's a bit full!", "Give me a sec, reorganizing!", "One moment!"),        "onyx" to listOf("Reorganizing.", "Compressing context.", "Processing."),        "sage" to listOf("Let me gather my thoughts.", "One moment, reorganizing.", "Give me a second."),        "echo" to listOf("Hold up, reorganizing...", "Give me a sec.", "One moment."),        "vanguard" to listOf("Reorganizing.", "Compressing.", "Stand by."),        "aria" to listOf("Ooh, let me reorganize!", "One second!", "Hold on!"),        "zenith" to listOf("Reorganizing.", "One moment.", "Processing."),        "default" to listOf("Give me a second.", "Reorganizing.", "One moment."),    ),)